using System;using System.Drawing;using System.Diagnostics;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Windows.Forms;
class IconChecks {
[DllImport("user32.dll")]static extern int GetGuiResources(IntPtr p,int flag);
[STAThread]static int Main(string[] a){try{var asm=Assembly.LoadFrom(a[0]);var type=asm.GetType("TechLounge.TrayGlyph");var create=type.GetMethod("Create");var colors=new[]{ColorTranslator.FromHtml("#2f7dff"),ColorTranslator.FromHtml("#5865f2"),ColorTranslator.FromHtml("#8b5cf6"),ColorTranslator.FromHtml("#ff2d6b"),ColorTranslator.FromHtml("#16c98a"),ColorTranslator.FromHtml("#12b6cf")};using(var sheet=new Bitmap(480,160))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(28,35,46));for(int i=0;i<6;i++){using(var idle=(Icon)create.Invoke(null,new object[]{colors[i],false,false}))using(var active=(Icon)create.Invoke(null,new object[]{colors[i],true,false}))using(var b=active.ToBitmap())using(var off=idle.ToBitmap()){if(off.GetPixel(16,2).A!=0)throw new Exception("Idle surface is not transparent");var pixel=b.GetPixel(16,2);if(Math.Abs(pixel.R-colors[i].R)>3||Math.Abs(pixel.G-colors[i].G)>3||Math.Abs(pixel.B-colors[i].B)>3)throw new Exception("Active theme mismatch");g.DrawIcon(idle,new Rectangle(i*80+16,16,48,48));g.DrawIcon(active,new Rectangle(i*80+16,96,48,48));}}sheet.Save(a[1]+"/tray-icon-states.png");}
using(var dark=(Icon)create.Invoke(null,new object[]{colors[0],false,false}))using(var light=(Icon)create.Invoke(null,new object[]{colors[0],false,true}))using(var d=dark.ToBitmap())using(var l=light.ToBitmap()){if(d.GetPixel(16,9).R<200||l.GetPixel(16,9).R>100)throw new Exception("Taskbar contrast mismatch");}
var trayType=asm.GetType("TechLounge.Tray");var flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;using(var tray=(IDisposable)Activator.CreateInstance(trayType,flags,null,new object[]{false},null)){var update=trayType.GetMethod("UpdateIcon");int g0=GetGuiResources(Process.GetCurrentProcess().Handle,0),u0=GetGuiResources(Process.GetCurrentProcess().Handle,1);for(int i=0;i<1000;i++)update.Invoke(tray,new object[]{i%2==0});int dg=GetGuiResources(Process.GetCurrentProcess().Handle,0)-g0,du=GetGuiResources(Process.GetCurrentProcess().Handle,1)-u0;if(dg>2||du>2)throw new Exception("Handle growth "+dg+","+du);File.WriteAllText(a[1]+"/checks.txt","PASS: six active theme colours; transparent idle icon; light/dark contrast; 1000 native NotifyIcon state swaps, GDI delta="+dg+", USER delta="+du+". No popup or worker launched.");}return 0;}catch(Exception e){File.WriteAllText(a[1]+"/checks.txt",e.ToString());return 1;}}
}
